@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  /* OOTDay Brand Color Palette */
  --ootday-crimson: #C41E3A;
  --ootday-cream: #F5F0EB;
  --ootday-brown: #4A3728;
  --ootday-gold: #B8860B;

  /* Legacy color references (for compatibility) */
  --color-primary: #C41E3A;
  --color-primary-light: #F5F0EB;
  --color-background: #F5F0EB;
  --color-text-primary: #4A3728;
  --color-text-secondary: #6B7280;
  --color-accent-pink: #FDF2F8;
  --color-border: #E5E7EB;

  /* Onboarding Colors - Updated to brand crimson */
  --onboarding-bg: #F5F0EB;
  --onboarding-primary: #C41E3A;
  --onboarding-primary-hover: #A01730;

  /* Converted to CSS custom properties for design system */
  --background: oklch(0.96 0.01 50); /* F5F0EB cream background */
  --foreground: oklch(0.3 0.02 40); /* 4A3728 brown text */
  --card: oklch(1 0 0); /* FFFFFF white cards */
  --card-foreground: oklch(0.3 0.02 40);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.3 0.02 40);
  --primary: oklch(0.5 0.18 15); /* C41E3A crimson */
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.3 0.02 40);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.3 0.02 40); /* 4A3728 brown for muted text */
  --accent: oklch(0.5 0.18 15); /* C41E3A crimson for accent */
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0); /* E5E7EB light gray */
  --input: oklch(0.5 0.18 15); /* C41E3A crimson border */
  --ring: oklch(0.5 0.18 15); /* C41E3A crimson for focus rings */
  --fashion-pink: oklch(0.95 0.05 350); /* FDF2F8 soft pink */
  --fashion-crimson: oklch(0.5 0.18 15); /* C41E3A brand crimson */
  --fashion-gold: oklch(0.65 0.08 75); /* B8860B brand gold */
  --chat-user: oklch(0.96 0.01 50); /* F5F0EB cream for user messages */
  --chat-assistant: oklch(1 0 0); /* White background for assistant messages */
  --chat-assistant-accent: oklch(0.5 0.18 15); /* C41E3A crimson avatar */
  --radius: 0.5rem; /* 8px for consistent rounded corners */
  --sidebar: oklch(1 0 0);
  --sidebar-foreground: oklch(0.3 0.02 40);
  --sidebar-primary: oklch(0.5 0.18 15); /* C41E3A crimson for active states */
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.3 0.02 40);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.5 0.18 15);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.2 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.2 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.6 0.18 15); /* Lighter crimson for dark mode */
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.6 0.18 15); /* Crimson accent for dark mode */
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.396 0.141 25.723);
  --destructive-foreground: oklch(0.637 0.237 25.331);
  --border: oklch(0.269 0 0);
  --input: oklch(0.6 0.18 15); /* Crimson border */
  --ring: oklch(0.6 0.18 15); /* Crimson focus ring */
  --fashion-pink: oklch(0.65 0.12 350);
  --fashion-crimson: oklch(0.6 0.18 15); /* Lighter crimson for dark mode */
  --fashion-gold: oklch(0.7 0.1 75);
  --chat-user: oklch(0.25 0.03 40); /* Dark brown-tinted user messages */
  --chat-assistant: oklch(0.22 0.01 0); /* Dark gray assistant messages */
  --chat-assistant-accent: oklch(0.6 0.18 15); /* Crimson avatar in dark mode */
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.6 0.18 15); /* Crimson for active states */
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(0.269 0 0);
  --sidebar-ring: oklch(0.6 0.18 15);
}

@theme inline {
  --font-sans: var(--font-noto-thai), var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-fashion-pink: var(--fashion-pink);
  --color-fashion-crimson: var(--fashion-crimson);
  --color-fashion-gold: var(--fashion-gold);
  --color-chat-user: var(--chat-user);
  --color-chat-assistant: var(--chat-assistant);
  --color-chat-assistant-accent: var(--chat-assistant-accent);
  --color-ootday-crimson: var(--ootday-crimson);
  --color-ootday-cream: var(--ootday-cream);
  --color-ootday-brown: var(--ootday-brown);
  --color-ootday-gold: var(--ootday-gold);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* Custom animations for fashion app */
@keyframes typing {
  0%,
  60%,
  100% {
    transform: translateY(0);
  }
  30% {
    transform: translateY(-10px);
  }
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes shimmer {
  0% {
    background-position: -1000px 0;
  }
  100% {
    background-position: 1000px 0;
  }
}

.animate-typing {
  animation: typing 1.4s infinite;
}

.animate-fade-in-up {
  animation: fadeInUp 0.5s ease-out;
}

.animate-shimmer {
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0) 0%,
    rgba(255, 255, 255, 0.4) 50%,
    rgba(255, 255, 255, 0) 100%
  );
  background-size: 1000px 100%;
  animation: shimmer 2s infinite;
}

/* Z-index hierarchy for proper overlay stacking */
.z-header {
  z-index: 40;
}

.z-sidebar {
  z-index: 30;
}

.z-dropdown {
  z-index: 50;
}

.z-modal-overlay {
  z-index: 60;
}

.z-modal-content {
  z-index: 61;
}

.z-toast {
  z-index: 100;
}

/* Prevent body scroll when modal is open */
.modal-open {
  overflow: hidden;
  padding-right: var(--scrollbar-width, 0);
}

/* Consistent backdrop styling */
.overlay-backdrop {
  background-color: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(4px);
}

/* Fix for mobile viewport issues */
@supports (height: 100dvh) {
  .min-h-screen {
    min-height: 100dvh;
  }
}

/* Mobile touch target sizing - minimum 44x44px */
@media (max-width: 768px) {
  .touch-target,
  button:not(.no-touch-target),
  a:not(.no-touch-target),
  [role="button"]:not(.no-touch-target) {
    min-width: 44px;
    min-height: 44px;
  }

  /* Gallery dots - proper touch size */
  .image-indicator {
    min-width: 44px;
    min-height: 44px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .image-indicator > * {
    width: 12px;
    height: 12px;
  }

  /* Size and color selectors */
  .size-selector,
  .color-selector {
    min-width: 44px;
    min-height: 44px;
    padding: 8px 12px;
  }
}

/* Onboarding Styles */
@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.onboarding-container {
  min-height: 100vh;
  background-color: var(--onboarding-bg);
}

.onboarding-screen-enter {
  animation: slideInRight 0.3s ease-out;
}

.onboarding-screen-exit {
  animation: slideInLeft 0.3s ease-out;
}

/* Onboarding circular arrow button */
.onboarding-next-button {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background-color: var(--onboarding-primary);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  cursor: pointer;
  transition: all 0.3s ease;
}

.onboarding-next-button:hover:not(:disabled) {
  background-color: var(--onboarding-primary-hover);
  transform: scale(1.05);
}

.onboarding-next-button:disabled {
  background-color: #D1D5DB;
  cursor: not-allowed;
}

/* Style carousel custom scrollbar */
.embla {
  overflow: hidden;
}

.embla__container {
  display: flex;
  gap: 1rem;
}

.embla__slide {
  flex: 0 0 280px;
  min-width: 0;
}

'use client'

import { useState } from 'react'
import { OutfitSearchBar } from './OutfitSearchBar'
import { FilterPills } from './FilterPills'
import { OutfitCard } from './OutfitCard'
import { OutfitCardSkeleton } from './OutfitCardSkeleton'
import { EmptyOutfitState } from './EmptyOutfitState'
import { useDebounce } from '@/lib/hooks/useDebounce'
import type { Outfit } from '@/lib/types'

interface OutfitDiscoveryProps {
  outfits: Outfit[]
  onSelectOutfit: (outfit: Outfit) => void
  isLoading?: boolean
  onClearFilters?: () => void
}

export function OutfitDiscovery({
  outfits,
  onSelectOutfit,
  isLoading = false,
  onClearFilters,
}: OutfitDiscoveryProps) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedOccasions, setSelectedOccasions] = useState<string[]>([])

  // Debounce search query
  const debouncedSearch = useDebounce(searchQuery, 300)

  // Filter outfits based on search and selected occasions
  const filteredOutfits = outfits.filter(outfit => {
    // Search filter
    if (debouncedSearch) {
      const query = debouncedSearch.toLowerCase()
      const matchesTitle = outfit.title.toLowerCase().includes(query)
      const matchesDesc = outfit.description?.toLowerCase().includes(query)
      if (!matchesTitle && !matchesDesc) return false
    }

    // Occasion filter (if implemented in outfit data)
    // if (selectedOccasions.length > 0) {
    //   if (!selectedOccasions.includes(outfit.style)) return false
    // }

    return true
  })

  return (
    <div className="h-full flex flex-col">
      {/* Search and Filter Pills - Sticky Header */}
      <div className="sticky top-0 bg-background z-10 border-b px-4 lg:px-6 py-3 lg:py-4 space-y-3">
        <h1 className="sr-only">Find your perfect outfit</h1>

        <OutfitSearchBar
          value={searchQuery}
          onChange={setSearchQuery}
        />

        <FilterPills
          selected={selectedOccasions}
          onChange={setSelectedOccasions}
        />
      </div>

      {/* Outfit Grid - Scrollable */}
      <div className="flex-1 overflow-y-auto px-4 lg:px-6 xl:px-8 py-6 lg:py-8">
        {isLoading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 gap-5 lg:gap-6 xl:gap-8">
            {Array.from({ length: 6 }).map((_, i) => (
              <OutfitCardSkeleton key={i} />
            ))}
          </div>
        ) : filteredOutfits.length === 0 ? (
          <EmptyOutfitState onClearFilters={onClearFilters} />
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 gap-5 lg:gap-6 xl:gap-8">
            {filteredOutfits.map((outfit) => (
              <OutfitCard
                key={outfit.id}
                outfit={outfit}
                onClick={() => onSelectOutfit(outfit)}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import type { Outfit, Product } from "@/lib/types"
import { ShoppingBag, MapPin, Plus, Heart, Share2, ChevronLeft, ChevronRight, Eye } from "lucide-react"

interface OutfitCardProps {
  outfit: Outfit
  onProductClick?: (product: Product) => void
  onShopLook?: (outfit: Outfit) => void
  onViewDetails?: (outfit: Outfit) => void
  onClick?: () => void
  className?: string
}

function OutfitCard({ outfit, onProductClick, onShopLook, onViewDetails, onClick, className }: OutfitCardProps) {
  const [currentImageIndex, setCurrentImageIndex] = useState(0)
  const [isLiked, setIsLiked] = useState(false)

  const nextImage = () => {
    setCurrentImageIndex((prev) => (prev + 1) % outfit.items.length)
  }

  const prevImage = () => {
    setCurrentImageIndex((prev) => (prev - 1 + outfit.items.length) % outfit.items.length)
  }

  const getAvailabilityColor = (availability: Product["availability"]) => {
    switch (availability) {
      case "in_stock":
        return "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"
      case "low_stock":
        return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200"
      case "out_of_stock":
        return "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200"
      default:
        return "bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200"
    }
  }

  const getAvailabilityText = (availability: Product["availability"]) => {
    switch (availability) {
      case "in_stock":
        return "In Stock"
      case "low_stock":
        return "Low Stock"
      case "out_of_stock":
        return "Out of Stock"
      default:
        return "Unknown"
    }
  }

  return (
    <Card
      className={`overflow-hidden animate-fade-in-up ${onClick ? 'cursor-pointer hover:shadow-lg transition-shadow' : ''} ${className}`}
      role="article"
      aria-label={`Outfit: ${outfit.title}`}
      onClick={onClick}
    >
      <CardContent className="p-0">
        {/* Hero Image Section */}
        <div className="relative aspect-[3/4] bg-muted">
          <img
            src={outfit.imageUrl || "/placeholder.svg?height=400&width=320"}
            alt={outfit.title}
            className="w-full h-full object-cover"
            loading="lazy"
            onError={(e) => {
              e.currentTarget.src = "/placeholder.svg?height=400&width=320"
            }}
          />

          {/* Image Navigation */}
          {outfit.items.length > 1 && (
            <>
              <Button
                size="sm"
                variant="secondary"
                className="absolute left-2 top-1/2 -translate-y-1/2 h-8 w-8 p-0 rounded-full bg-background/80 backdrop-blur"
                onClick={prevImage}
              >
                <ChevronLeft className="w-4 h-4" />
              </Button>
              <Button
                size="sm"
                variant="secondary"
                className="absolute right-2 top-1/2 -translate-y-1/2 h-8 w-8 p-0 rounded-full bg-background/80 backdrop-blur"
                onClick={nextImage}
              >
                <ChevronRight className="w-4 h-4" />
              </Button>
            </>
          )}

          {/* Action Buttons */}
          <div className="absolute top-3 right-3 flex gap-2">
            <Button
              size="sm"
              variant="secondary"
              className="h-8 w-8 p-0 rounded-full bg-white/90 hover:bg-white backdrop-blur border border-gray-200 shadow-sm"
              onClick={() => setIsLiked(!isLiked)}
              aria-label={isLiked ? "Unlike outfit" : "Like outfit"}
              aria-pressed={isLiked}
            >
              <Heart className={`w-5 h-5 ${isLiked ? "fill-red-500 text-red-500" : "text-gray-600 hover:text-gray-800"}`} />
            </Button>
            <Button
              size="sm"
              variant="secondary"
              className="h-8 w-8 p-0 rounded-full bg-white/90 hover:bg-white backdrop-blur border border-gray-200 shadow-sm"
              aria-label="Share outfit"
            >
              <Share2 className="w-5 h-5 text-gray-600 hover:text-gray-800" />
            </Button>
          </div>

          {/* Image Indicators */}
          {outfit.items.length > 1 && (
            <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-1">
              {outfit.items.map((_, index) => (
                <button
                  key={index}
                  className="image-indicator"
                  onClick={() => setCurrentImageIndex(index)}
                  aria-label={`View item ${index + 1}`}
                >
                  <div
                    className={`w-2 h-2 rounded-full transition-colors ${
                      index === currentImageIndex ? "bg-white" : "bg-white/50"
                    }`}
                  />
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="p-3 md:p-4 space-y-3 md:space-y-4">
          {/* Title and Price Section - Fixed layout */}
          <div className="space-y-2">
            <div className="flex items-start gap-4">
              <div className="flex-1 min-w-0">
                <h3 className="font-bold text-xs md:text-sm text-balance leading-tight line-clamp-2">
                  {outfit.title}
                </h3>
                <p className="text-muted-foreground text-[11px] md:text-xs text-pretty mt-1 line-clamp-2">
                  {outfit.description}
                </p>
              </div>
              <div className="text-right flex-shrink-0">
                <p className="text-base md:text-lg font-bold">฿{outfit.totalPrice.toLocaleString()}</p>
                <p className="text-[10px] md:text-xs text-muted-foreground whitespace-nowrap mt-0.5">{outfit.items.length} items</p>
              </div>
            </div>
          </div>

          {/* Product Items Section - Improved spacing */}
          <div className="space-y-2 md:space-y-3">
            <h4 className="text-[11px] md:text-xs font-semibold">Items in this look:</h4>
            <div className="flex gap-2 md:gap-3 overflow-x-auto pb-2 -mx-1 px-1 scrollbar-hide">
              {outfit.items.map((product) => (
                <div
                  key={product.sku}
                  className="flex-shrink-0 w-24 md:w-28 cursor-pointer group"
                  onClick={() => onProductClick?.(product)}
                >
                  <div className="relative">
                    <div className="aspect-square w-full rounded-lg overflow-hidden bg-muted">
                      <img
                        src={product.imageUrl || "/placeholder.svg"}
                        alt={product.name}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform"
                        loading="lazy"
                        onError={(e) => {
                          e.currentTarget.src = "/placeholder.svg"
                        }}
                      />
                    </div>
                    <Badge
                      className={`absolute top-1 right-1 text-[10px] md:text-xs px-1.5 md:px-2 py-0.5 ${getAvailabilityColor(product.availability)}`}
                    >
                      {getAvailabilityText(product.availability)}
                    </Badge>
                  </div>
                  <div className="mt-1.5 md:mt-2 space-y-0.5">
                    <p className="text-[9px] md:text-[10px] font-medium text-balance leading-tight line-clamp-2">
                      {product.name}
                    </p>
                    <p className="text-[9px] md:text-[10px] text-muted-foreground line-clamp-1">{product.brand}</p>
                    <p className="text-[10px] md:text-xs font-bold">฿{product.price.toLocaleString()}</p>
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    className="w-full mt-1.5 md:mt-2 h-6 md:h-7 text-[10px] md:text-xs bg-transparent"
                    disabled={product.availability === "out_of_stock"}
                  >
                    <Eye className="w-3 md:w-3.5 h-3 md:h-3.5 mr-1" />
                    View Look
                  </Button>
                </div>
              ))}
            </div>
          </div>

          {/* Action Buttons - Improved responsive sizing */}
          <div className="flex gap-2">
            {onViewDetails && (
              <Button
                variant="outline"
                className="flex-1 h-9 md:h-10 text-xs md:text-sm bg-transparent"
                onClick={() => onViewDetails(outfit)}
              >
                View Details
              </Button>
            )}
            <Button
              className={`${onViewDetails ? 'flex-1' : 'flex-1'} h-9 md:h-10 text-xs md:text-sm`}
              onClick={() => onShopLook?.(outfit)}
            >
              <ShoppingBag className="w-4 h-4 mr-2" />
              Shop Look
            </Button>
            <Button variant="outline" size="sm" className="px-2.5 md:px-3 h-9 md:h-10 bg-transparent flex-shrink-0">
              <MapPin className="w-4 h-4" />
            </Button>
          </div>

          {/* Store Availability - Only show if locations exist */}
          {(() => {
            const storeLocations = Array.from(new Set(outfit.items.flatMap((item) => item.storeLocations || [])))
            // If no locations from data, use default Central locations
            const locations = storeLocations.length > 0 ? storeLocations : ['Central Chidlom', 'Central World', 'Central Ladprao']

            return (
              <div className="pt-3 md:pt-4 border-t space-y-2.5">
                <p className="text-xs text-muted-foreground">Available at:</p>
                <div className="flex flex-wrap gap-1.5">
                  {locations.map((location) => (
                    <Badge key={location} variant="secondary" className="text-xs px-2 py-0.5">
                      {location}
                    </Badge>
                  ))}
                </div>
              </div>
            )
          })()}
        </div>
      </CardContent>
    </Card>
  )
}

