              <div className="flex gap-4 pl-4 pr-8">
                {filteredOutfits.map((outfit) => (
                  <div key={outfit.id} className="flex-[0_0_160px] min-w-0">
                    <OutfitCarouselCard
                      outfit={outfit}
                      isSelected={isSelected(outfit.id)}
                      onToggle={() => toggleOutfit(outfit)}
                    />
                  </div>
